// Static server for the demo, tests and benchmarks. Cross-origin isolated (COOP/COEP), so
// performance.now() has 5 µs resolution.
//
//   node viewer-kit/scripts/serve.mjs [port]     then open http://localhost:PORT/kit/demo/
//
//   /kit/      viewer-kit/ (dist/, demo/, test/)
//   /corpus/   codec-corpus/formats/
//   /series/   viewer-kit/data/   (generated by bench/make_series.py)
import { createReadStream, existsSync, statSync } from "node:fs";
import { createServer } from "node:http";
import { dirname, extname, join, normalize } from "node:path";
import { fileURLToPath } from "node:url";

const KIT = join(dirname(fileURLToPath(import.meta.url)), "..");
const ROOT = join(KIT, "..");
const TYPES = { ".html": "text/html; charset=utf-8", ".mjs": "text/javascript", ".js": "text/javascript", ".wasm": "application/wasm", ".json": "application/json", ".css": "text/css", ".dcm": "application/dicom" };

export function serve(port = 0) {
  const roots = { "/kit/": KIT, "/corpus/": join(ROOT, "codec-corpus", "formats"), "/series/": join(KIT, "data") };
  const server = createServer((req, res) => {
    let url = decodeURIComponent(new URL(req.url, "http://x").pathname);
    if (url === "/" ) url = "/kit/demo/index.html";
    if (url.endsWith("/")) url += "index.html";
    const prefix = Object.keys(roots).find((p) => url.startsWith(p));
    const file = prefix && normalize(join(roots[prefix], url.slice(prefix.length)));
    if (!file || !file.startsWith(roots[prefix]) || !existsSync(file) || !statSync(file).isFile()) {
      res.writeHead(404).end();
      return;
    }
    res.writeHead(200, {
      "content-type": TYPES[extname(file)] ?? "application/octet-stream",
      "cross-origin-opener-policy": "same-origin",
      "cross-origin-embedder-policy": "require-corp",
      "cross-origin-resource-policy": "same-origin",
      "cache-control": "no-store",
    });
    createReadStream(file).pipe(res);
  });
  return new Promise((resolve) => server.listen(port, "127.0.0.1", () => resolve({ server, origin: `http://localhost:${server.address().port}` })));
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const { origin } = await serve(Number(process.argv[2] ?? 8787));
  console.log(`${origin}/kit/demo/`);
}
